import{_ as e,o as n,c as l,a4 as d}from"./chunks/framework.BWWfBZka.js";const x=JSON.parse('{"title":"99 प्रमुख सिस्टम डिज़ाइन कौशल और अवधारणा मैट्रिक्स","description":"","frontmatter":{},"headers":[],"relativePath":"hi/02_Skills_Matrix.md","filePath":"hi/02_Skills_Matrix.md","lastUpdated":1788997251000}'),s={name:"hi/02_Skills_Matrix.md"};function a(r,t,i,o,g,c){return n(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="_99-प्रमुख-सिस्टम-डिज़ाइन-कौशल-और-अवधारणा-मैट्रिक्स" tabindex="-1">99 प्रमुख सिस्टम डिज़ाइन कौशल और अवधारणा मैट्रिक्स <a class="header-anchor" href="#_99-प्रमुख-सिस्टम-डिज़ाइन-कौशल-और-अवधारणा-मैट्रिक्स" aria-label="Permalink to &quot;99 प्रमुख सिस्टम डिज़ाइन कौशल और अवधारणा मैट्रिक्स&quot;">​</a></h1><hr><p><strong>कुल प्रविष्टियां</strong>: 99</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">श्रेणी</th><th style="text-align:left;">अवधारणा / कौशल</th><th style="text-align:center;">स्तर</th><th style="text-align:left;">यह क्यों महत्वपूर्ण है</th><th style="text-align:left;">साक्षात्कार में कैसे पूछा जाता है</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Scalability: vertical versus horizontal</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">The first fork in every design discussion.</td><td style="text-align:left;">&#39;This works on one server. Now handle 10x traffic.&#39;</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Latency versus throughput</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">Two different problems that beginners conflate constantly.</td><td style="text-align:left;">&#39;Do you optimise for latency or throughput here? Why?&#39;</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Availability, reliability and durability</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">Three distinct guarantees with different costs.</td><td style="text-align:left;">&#39;What does five nines actually cost you?&#39;</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>CAP theorem and PACELC</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The framing behind every distributed database choice.</td><td style="text-align:left;">&#39;Is this system CP or AP? Justify it.&#39;</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Consistency models (strong, eventual, causal)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Determines what your users can observe.</td><td style="text-align:left;">&#39;A user posts and does not see it. Is that acceptable here?&#39;</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Back-of-the-envelope estimation</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">The first five minutes of every design interview.</td><td style="text-align:left;">&#39;How much storage does this need per year?&#39;</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Functional versus non-functional requirements</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">Clarifying these first is the single highest-scoring habit.</td><td style="text-align:left;">Watching whether you gather requirements before designing.</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Single points of failure</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Every box you draw is a thing that can fail.</td><td style="text-align:left;">&#39;What happens when this component dies?&#39;</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Trade-off thinking</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">There is no correct design, only justified ones.</td><td style="text-align:left;">The whole interview is an assessment of this.</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>Networking</strong></td><td style="text-align:left;"><strong>DNS and how requests are routed</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">The entry point of every system you design.</td><td style="text-align:left;">&#39;Walk me through what happens before the request reaches you.&#39;</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>Networking</strong></td><td style="text-align:left;"><strong>HTTP, HTTPS and TLS</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">The protocol layer of almost every design.</td><td style="text-align:left;">&#39;Where does TLS terminate in your architecture?&#39;</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>Networking</strong></td><td style="text-align:left;"><strong>TCP versus UDP</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Video, gaming and telemetry make different choices.</td><td style="text-align:left;">&#39;Why would you use UDP for this?&#39;</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>Networking</strong></td><td style="text-align:left;"><strong>WebSockets, long polling and Server-Sent Events</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Every real-time feature needs one of these.</td><td style="text-align:left;">&#39;How does the client learn about a new message?&#39;</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>Networking</strong></td><td style="text-align:left;"><strong>gRPC and protocol buffers</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Internal service communication at scale.</td><td style="text-align:left;">&#39;REST or gRPC between these services?&#39;</td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>Networking</strong></td><td style="text-align:left;"><strong>Content Delivery Networks</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Static assets, video and global latency.</td><td style="text-align:left;">&#39;Users in Australia see 3 second loads. Fix it.&#39;</td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>Networking</strong></td><td style="text-align:left;"><strong>Proxies: forward, reverse and API gateway</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The layer where auth, routing and rate limiting live.</td><td style="text-align:left;">&#39;Where does authentication happen in this design?&#39;</td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>Load Balancing</strong></td><td style="text-align:left;"><strong>Load balancer types and placement</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">Appears in essentially every design you will draw.</td><td style="text-align:left;">&#39;Where do the load balancers go, and how many?&#39;</td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>Load Balancing</strong></td><td style="text-align:left;"><strong>Algorithms (round robin, least connections, hashing)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The choice affects cache hit rates and fairness.</td><td style="text-align:left;">&#39;Why consistent hashing here rather than round robin?&#39;</td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>Load Balancing</strong></td><td style="text-align:left;"><strong>Layer 4 versus Layer 7 load balancing</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Transport versus application-aware routing.</td><td style="text-align:left;">&#39;What can an L7 balancer do that L4 cannot?&#39;</td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>Load Balancing</strong></td><td style="text-align:left;"><strong>Health checks and failover</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">How the system removes a dead node automatically.</td><td style="text-align:left;">&#39;How does traffic stop going to a failed server?&#39;</td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>Load Balancing</strong></td><td style="text-align:left;"><strong>Sticky sessions and why to avoid them</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Statelessness is what makes horizontal scaling work.</td><td style="text-align:left;">&#39;Why is holding session state in memory a problem?&#39;</td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>Cache strategies (cache-aside, write-through, write-back)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The choice determines your consistency and failure behaviour.</td><td style="text-align:left;">&#39;Which caching strategy, and what breaks with each?&#39;</td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>Cache eviction policies (LRU, LFU, TTL)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">What leaves the cache when it is full.</td><td style="text-align:left;">&#39;Design an LRU cache.&#39; Also a common coding question.</td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>Cache invalidation</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Famously one of the two hard problems in computing.</td><td style="text-align:left;">&#39;The data changed. How does the cache find out?&#39;</td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>Redis and Memcached</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The two standard distributed cache choices.</td><td style="text-align:left;">&#39;Redis or Memcached here? What is the difference?&#39;</td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>Multi-level caching (browser, CDN, application, database)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Caching happens at four layers, not one.</td><td style="text-align:left;">&#39;Where would you cache in this design?&#39;</td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>Thundering herd and cache stampede</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">What happens when a hot key expires under load.</td><td style="text-align:left;">&#39;The cache expires and the database falls over. Prevent it.&#39;</td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>SQL versus NoSQL selection</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">The most common design question after scaling.</td><td style="text-align:left;">&#39;Postgres or Cassandra here? Defend it.&#39;</td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Relational modelling and normalisation</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">The schema is the most expensive thing to change later.</td><td style="text-align:left;">&#39;Design the schema for this system.&#39;</td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Indexing and query performance</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The difference between 5ms and 5 seconds.</td><td style="text-align:left;">&#39;This query is slow at scale. What do you do?&#39;</td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Replication (leader-follower, multi-leader, leaderless)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Read scaling and availability.</td><td style="text-align:left;">&#39;How do you scale reads? What breaks?&#39;</td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Replication lag and read-your-writes</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">The user who cannot see their own comment.</td><td style="text-align:left;">&#39;A user updates their profile and sees the old one. Why?&#39;</td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Sharding and partitioning strategies</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The main technique for scaling writes.</td><td style="text-align:left;">&#39;How do you shard this? What is your partition key?&#39;</td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Consistent hashing</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Adding and removing nodes without reshuffling everything.</td><td style="text-align:left;">&#39;How do you add a shard without moving all the data?&#39;</td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Hot partitions and skew</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">One celebrity user destroys a naive sharding scheme.</td><td style="text-align:left;">&#39;Your partition key is user ID. What about the top 1% of users?&#39;</td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>ACID transactions and isolation levels</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Money and inventory correctness.</td><td style="text-align:left;">&#39;Two users buy the last item. What happens?&#39;</td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Distributed transactions and two-phase commit</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Why microservices avoid them.</td><td style="text-align:left;">&#39;How do you keep two services consistent without 2PC?&#39;</td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Saga pattern and compensating transactions</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">The practical answer to distributed consistency.</td><td style="text-align:left;">&#39;Order placed, payment failed. Now what?&#39;</td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>NoSQL types (key-value, document, wide-column, graph)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Four families with genuinely different use cases.</td><td style="text-align:left;">&#39;Which NoSQL family fits this access pattern?&#39;</td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Time-series and analytical databases</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Metrics, logging and OLAP workloads.</td><td style="text-align:left;">&#39;Where do you store 2 billion events per day?&#39;</td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Database connection pooling</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">A classic production failure at scale.</td><td style="text-align:left;">&#39;Your service scales up and the database refuses connections.&#39;</td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>Storage</strong></td><td style="text-align:left;"><strong>Object storage versus block versus file</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Images, video and backups all live in object storage.</td><td style="text-align:left;">&#39;Where do the uploaded videos go?&#39;</td></tr><tr><td style="text-align:center;">43</td><td style="text-align:left;"><strong>Storage</strong></td><td style="text-align:left;"><strong>Blob storage and presigned URLs</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Uploading without routing bytes through your servers.</td><td style="text-align:left;">&#39;A user uploads a 2GB file. Design the path.&#39;</td></tr><tr><td style="text-align:center;">44</td><td style="text-align:left;"><strong>Storage</strong></td><td style="text-align:left;"><strong>Data retention, archival and tiering</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Storage cost management at scale.</td><td style="text-align:left;">&#39;This is 40TB per month. What does it cost in year three?&#39;</td></tr><tr><td style="text-align:center;">45</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Message queues and why they exist</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Decoupling, buffering and absorbing spikes.</td><td style="text-align:left;">&#39;The email send slows checkout. Fix it.&#39;</td></tr><tr><td style="text-align:center;">46</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Kafka and log-based streaming</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The default event backbone at scale.</td><td style="text-align:left;">&#39;Explain partitions and consumer groups.&#39;</td></tr><tr><td style="text-align:center;">47</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>RabbitMQ, SQS and traditional brokers</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Task queues versus event streams.</td><td style="text-align:left;">&#39;Kafka or SQS here? What is the difference?&#39;</td></tr><tr><td style="text-align:center;">48</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Pub/sub versus point-to-point</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">One consumer or many.</td><td style="text-align:left;">&#39;Multiple services need this event. Design it.&#39;</td></tr><tr><td style="text-align:center;">49</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Delivery guarantees (at-most, at-least, exactly-once)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Exactly-once is harder than candidates think.</td><td style="text-align:left;">&#39;How do you achieve exactly-once end to end?&#39;</td></tr><tr><td style="text-align:center;">50</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Idempotency and deduplication</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Retries are guaranteed; double-charging must not be.</td><td style="text-align:left;">&#39;The payment webhook fires twice. What must be true?&#39;</td></tr><tr><td style="text-align:center;">51</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Dead letter queues and poison messages</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The message that fails forever.</td><td style="text-align:left;">&#39;A message keeps failing. What happens to it?&#39;</td></tr><tr><td style="text-align:center;">52</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Event-driven architecture and event sourcing</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Decoupled systems and auditable state.</td><td style="text-align:left;">&#39;What does event sourcing buy you, and what does it cost?&#39;</td></tr><tr><td style="text-align:center;">53</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Monolith versus microservices</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Most teams should start with a monolith. Saying so scores.</td><td style="text-align:left;">&#39;Should we split this? Usually no. Explain why.&#39;</td></tr><tr><td style="text-align:center;">54</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Service boundaries and domain-driven design</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Where to cut is the hard part, not how.</td><td style="text-align:left;">&#39;How would you split this system into services?&#39;</td></tr><tr><td style="text-align:center;">55</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>API design (REST, GraphQL, gRPC)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The contract between every component you draw.</td><td style="text-align:left;">&#39;Design the API for this feature.&#39;</td></tr><tr><td style="text-align:center;">56</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>API gateway and backend for frontend</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The edge layer in a microservices design.</td><td style="text-align:left;">&#39;Twelve services and three clients. Design the entry point.&#39;</td></tr><tr><td style="text-align:center;">57</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Service discovery and service mesh</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">How services find each other dynamically.</td><td style="text-align:left;">&#39;How does service A know where service B is?&#39;</td></tr><tr><td style="text-align:center;">58</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Stateless services and externalised state</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The precondition for horizontal scaling.</td><td style="text-align:left;">&#39;Why must this service be stateless?&#39;</td></tr><tr><td style="text-align:center;">59</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Read-heavy versus write-heavy design</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The ratio changes every decision you make.</td><td style="text-align:left;">&#39;This is 1000:1 read to write. What changes?&#39;</td></tr><tr><td style="text-align:center;">60</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Fan-out on read versus fan-out on write</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">The central trade-off in feed design.</td><td style="text-align:left;">&#39;Design a news feed. Which fan-out, and why?&#39;</td></tr><tr><td style="text-align:center;">61</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Multi-region and geo-distribution</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Global latency and disaster recovery.</td><td style="text-align:left;">&#39;Users in three continents. Design for it.&#39;</td></tr><tr><td style="text-align:center;">62</td><td style="text-align:left;"><strong>Architecture</strong></td><td style="text-align:left;"><strong>Lambda and Kappa architectures</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Batch plus streaming, or streaming only.</td><td style="text-align:left;">&#39;Do you need a batch layer here?&#39;</td></tr><tr><td style="text-align:center;">63</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Redundancy and failover</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Every critical component needs a spare.</td><td style="text-align:left;">&#39;This database is a single point of failure. Fix it.&#39;</td></tr><tr><td style="text-align:center;">64</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Circuit breakers, retries and exponential backoff</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Preventing a slow service from taking down everything.</td><td style="text-align:left;">&#39;The downstream service is slow. What does your user see?&#39;</td></tr><tr><td style="text-align:center;">65</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Timeouts and bulkheads</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Containing failure rather than propagating it.</td><td style="text-align:left;">&#39;How do you stop one slow dependency exhausting your threads?&#39;</td></tr><tr><td style="text-align:center;">66</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Rate limiting and throttling algorithms</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Protecting cost, capacity and fairness.</td><td style="text-align:left;">&#39;Design a rate limiter.&#39; A very common standalone question.</td></tr><tr><td style="text-align:center;">67</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Graceful degradation and load shedding</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Serving something rather than failing entirely.</td><td style="text-align:left;">&#39;Traffic is 5x forecast. What do you turn off first?&#39;</td></tr><tr><td style="text-align:center;">68</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Backpressure</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Telling upstream to slow down rather than collapsing.</td><td style="text-align:left;">&#39;The consumer cannot keep up. What now?&#39;</td></tr><tr><td style="text-align:center;">69</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Disaster recovery, RTO and RPO</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">How much downtime and data loss is acceptable.</td><td style="text-align:left;">&#39;A region goes down. What is your recovery plan?&#39;</td></tr><tr><td style="text-align:center;">70</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Chaos engineering</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Proving resilience rather than assuming it.</td><td style="text-align:left;">&#39;How do you know your failover actually works?&#39;</td></tr><tr><td style="text-align:center;">71</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>Logging, metrics and traces</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The three pillars, and what each is for.</td><td style="text-align:left;">&#39;How do you debug a slow request across eight services?&#39;</td></tr><tr><td style="text-align:center;">72</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>Distributed tracing and correlation IDs</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Following one request through a distributed system.</td><td style="text-align:left;">&#39;Where is the latency in this chain?&#39;</td></tr><tr><td style="text-align:center;">73</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>SLIs, SLOs and error budgets</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Turning reliability into a measurable commitment.</td><td style="text-align:left;">&#39;What is your SLO, and what happens when you miss it?&#39;</td></tr><tr><td style="text-align:center;">74</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>Alerting and on-call design</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Alerting on symptoms, not causes.</td><td style="text-align:left;">&#39;What do you alert on, and what do you deliberately not?&#39;</td></tr><tr><td style="text-align:center;">75</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>Health checks and readiness probes</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">How orchestrators know a service is usable.</td><td style="text-align:left;">&#39;What is the difference between liveness and readiness?&#39;</td></tr><tr><td style="text-align:center;">76</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>Authentication and authorisation at scale</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Every system with users needs both.</td><td style="text-align:left;">&#39;How does a request get authenticated across services?&#39;</td></tr><tr><td style="text-align:center;">77</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>OAuth2, OIDC and JWT in system design</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The standard token flows.</td><td style="text-align:left;">&#39;Where is the token validated, and by whom?&#39;</td></tr><tr><td style="text-align:center;">78</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>Encryption in transit and at rest</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">A baseline expectation and a compliance requirement.</td><td style="text-align:left;">&#39;How is this sensitive data protected?&#39;</td></tr><tr><td style="text-align:center;">79</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>Secrets management</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Credentials must not live in code or config files.</td><td style="text-align:left;">&#39;Where do the production credentials live?&#39;</td></tr><tr><td style="text-align:center;">80</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>DDoS protection and WAF</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Surviving hostile traffic.</td><td style="text-align:left;">&#39;Someone floods your API. Respond.&#39;</td></tr><tr><td style="text-align:center;">81</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>Data privacy, GDPR and DPDP in design</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Regulation shapes architecture, especially data location.</td><td style="text-align:left;">&#39;A user requests deletion. Where is their data?&#39;</td></tr><tr><td style="text-align:center;">82</td><td style="text-align:left;"><strong>Performance</strong></td><td style="text-align:left;"><strong>Capacity planning and load testing</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Knowing your ceiling before your users find it.</td><td style="text-align:left;">&#39;How many servers do you need? Show your working.&#39;</td></tr><tr><td style="text-align:center;">83</td><td style="text-align:left;"><strong>Performance</strong></td><td style="text-align:left;"><strong>Connection management and keep-alive</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Connection overhead at high request rates.</td><td style="text-align:left;">&#39;What is the cost of opening a connection per request?&#39;</td></tr><tr><td style="text-align:center;">84</td><td style="text-align:left;"><strong>Performance</strong></td><td style="text-align:left;"><strong>Compression and payload optimisation</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Bandwidth cost and mobile latency.</td><td style="text-align:left;">&#39;Users are on 3G. What do you change?&#39;</td></tr><tr><td style="text-align:center;">85</td><td style="text-align:left;"><strong>Performance</strong></td><td style="text-align:left;"><strong>Batching and request coalescing</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Reducing round trips and downstream load.</td><td style="text-align:left;">&#39;You are making 200 calls per page. Fix it.&#39;</td></tr><tr><td style="text-align:center;">86</td><td style="text-align:left;"><strong>Performance</strong></td><td style="text-align:left;"><strong>Database query optimisation at scale</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The most common actual bottleneck.</td><td style="text-align:left;">&#39;Where is the bottleneck in this design?&#39; Usually the database.</td></tr><tr><td style="text-align:center;">87</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>SOLID principles</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The framing for every LLD code review.</td><td style="text-align:left;">&#39;Which principle does this design violate?&#39;</td></tr><tr><td style="text-align:center;">88</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Creational patterns (factory, builder, singleton)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Object construction problems.</td><td style="text-align:left;">&#39;Design a notification system with multiple channels.&#39;</td></tr><tr><td style="text-align:center;">89</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Structural patterns (adapter, decorator, facade)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Composing and wrapping behaviour.</td><td style="text-align:left;">&#39;Add logging to this without modifying it.&#39;</td></tr><tr><td style="text-align:center;">90</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Behavioural patterns (strategy, observer, state)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Varying behaviour at runtime.</td><td style="text-align:left;">&#39;Design a payment system supporting five providers.&#39;</td></tr><tr><td style="text-align:center;">91</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Class diagrams and UML basics</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The output format of an LLD round.</td><td style="text-align:left;">&#39;Draw the classes and their relationships.&#39;</td></tr><tr><td style="text-align:center;">92</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Concurrency in object design</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Thread safety in shared components.</td><td style="text-align:left;">&#39;Is this design thread-safe? Make it so.&#39;</td></tr><tr><td style="text-align:center;">93</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Common LLD problems (parking lot, elevator, BookMyShow)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Amazon and Indian product companies ask these directly.</td><td style="text-align:left;">&#39;Design a parking lot system.&#39; Extremely common in India.</td></tr><tr><td style="text-align:center;">94</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Structuring the 45-minute interview</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Requirements, estimation, high level, deep dive, wrap up.</td><td style="text-align:left;">Running out of time is the most common failure mode.</td></tr><tr><td style="text-align:center;">95</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Driving the conversation</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The candidate leads; the interviewer probes.</td><td style="text-align:left;">Silence and waiting to be asked both score badly.</td></tr><tr><td style="text-align:center;">96</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Drawing clear diagrams</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Your diagram is the artifact being judged.</td><td style="text-align:left;">Illegible boxes and unlabelled arrows cost marks.</td></tr><tr><td style="text-align:center;">97</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Handling a topic you do not know</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Reasoning from first principles beats bluffing.</td><td style="text-align:left;">How you behave at the edge of your knowledge is assessed.</td></tr><tr><td style="text-align:center;">98</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Justifying every choice with a trade-off</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">&#39;I would use Redis&#39; is incomplete. Why, and what does it cost?</td><td style="text-align:left;">Every unjustified component invites a challenge.</td></tr><tr><td style="text-align:center;">99</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Reading real engineering blogs</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">The gap between textbook design and production reality.</td><td style="text-align:left;">&#39;Have you read how any real company solved this?&#39;</td></tr></tbody></table>',4)])])}const f=e(s,[["render",a]]);export{x as __pageData,f as default};
